// Builds the Web client bundle from the ordered plain-JavaScript fragments in client/src/.
// The Harness Web module loader loads one file that registers a lazy factory for this package id;
// each fragment is plain script text (no imports/exports), concatenated inside that factory, so a
// missing or reordered fragment fails loudly at `node --check`/page load rather than at runtime.
//
// The concatenated factory body is then minified by esbuild (transform, not bundle: `require('react')`
// must stay a call into the loader) and shipped with an external source map. esbuild is pinned exactly
// so `--check` can compare the generated bytes; a different esbuild version is a deliberate change.
//
// Fragments may be written in JSX or in plain `h(...)` calls: the loader is `jsx`, and JSX compiles to
// the same `h` binding the prelude defines, so a file can be migrated one commit at a time without
// touching the artifact contract or the runtime.
import { readFileSync, writeFileSync, readdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { createRequire } from 'node:module'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const sourceDir = join(root, 'client', 'src')
const outFile = join(root, 'client', 'index.js')
const mapFile = `${outFile}.map`
const PACKAGE = '@mystic7c/dsh-superagent-panel'

const require = createRequire(import.meta.url)
let esbuild
try {
  esbuild = require('esbuild')
} catch (error) {
  console.error('build-client needs esbuild: run `npm ci` in the repo root first.')
  console.error(error instanceof Error ? error.message : String(error))
  process.exit(2)
}

const files = readdirSync(sourceDir).filter(name => name.endsWith('.js')).sort()
if (files.length === 0) throw new Error('client/src has no fragments')

const body = files.map(name => {
  const text = readFileSync(join(sourceDir, name), 'utf8').trimEnd()
  return `\n// ---- ${name} ----\n${text}\n`
}).join('\n')

const banner = `// Generated by scripts/build-client.mjs from client/src/*.js — do not edit by hand.
// Registers the Superagent management panel: sidebar icon in \`sidebar.panellist\` and the full
// management panel in the keyed \`main\` slot. Plain React only; data comes from the host half over
// same-origin \`/superagent/api\` routes. Minified by esbuild; read client/src and index.js.map.
`
const prelude = `
const { useState, useEffect, useRef, useMemo, useCallback, useLayoutEffect, useContext, createContext, Fragment } = React
const h = React.createElement
`
const source = `window.__ModuleLoader__.load({
  id: ${JSON.stringify(PACKAGE)},
  factory(require) {
    const React = require('react')
${prelude}${body}
    return { inject, apply }
  },
})
`

// transform (not bundle) keeps `require('react')` as a loader call; minify shrinks the shipped artifact.
// `jsxFactory: 'h'` is deliberate: JSX and hand-written `h(...)` calls compile to the same runtime call,
// so fragments can migrate incrementally and the factory scope keeps its single `h` binding.
const result = esbuild.transformSync(source, {
  loader: 'jsx',
  jsx: 'transform',
  jsxFactory: 'h',
  jsxFragment: 'React.Fragment',
  target: 'es2022',
  minify: true,
  legalComments: 'none',
  sourcemap: 'external',
  sourcefile: 'client/src/*.js',
  charset: 'utf8',
})
if (result.warnings.length > 0) for (const warning of result.warnings) console.error(`warning: ${warning.text}`)
const output = `${banner}${result.code}//# sourceMappingURL=index.js.map\n`
const map = `${result.map}\n`

if (process.argv.includes('--check')) {
  const current = (() => { try { return readFileSync(outFile, 'utf8') } catch { return undefined } })()
  const currentMap = (() => { try { return readFileSync(mapFile, 'utf8') } catch { return undefined } })()
  if (current !== output) {
    console.error('client/index.js is out of date; run `node scripts/build-client.mjs`')
    process.exit(1)
  }
  if (currentMap !== map) {
    console.error('client/index.js.map is out of date; run `node scripts/build-client.mjs`')
    process.exit(1)
  }
  console.log(`client/index.js is up to date (${files.length} fragments, ${Buffer.byteLength(output)} bytes)`)
} else {
  writeFileSync(outFile, output)
  writeFileSync(mapFile, map)
  console.log(`wrote ${outFile} (${files.length} fragments, ${Buffer.byteLength(output)} bytes)`)
}
